/*
 * prog27_soundex.c
 *
 * Re‑implementation of the original program whose behaviour was observed
 * in the supplied binary.  The program computes the Soundex code of the
 * first command‑line argument and prints it.  If no argument is supplied
 * (or the argument is an empty string) the program prints the literal
 * string “EMPTY”.
 *
 * The implementation follows the classic Soundex algorithm:
 *
 *   1. Keep the first letter of the word (converted to upper case).
 *   2. Replace each subsequent letter by a digit according to the table:
 *
 *          B, F, P, V           -> 1
 *          C, G, J, K, Q, S, X, Z -> 2
 *          D, T                -> 3
 *          L                   -> 4
 *          M, N                -> 5
 *          R                   -> 6
 *          A, E, I, O, U, H, W, Y -> 0 (ignored)
 *
 *   3. Remove consecutive duplicate digits.
 *   4. Remove all zeros.
 *   5. Keep the first three digits (pad with '0' if fewer than three).
 *   6. Output the first letter followed by the three digits.
 *
 * The binary also contained a helper function `soundex_digit` that maps a
 * single character to its Soundex digit; the same logic is reproduced here.
 *
 * The program is deliberately simple and uses only the standard C library
 * functions required by the original binary (`puts`, `strlen`).
 */

#include <stdio.h>
#include <string.h>
#include <ctype.h>

/* ----------------------------------------------------------------------
 * soundex_digit
 *
 * Return the Soundex digit for a given (upper‑case) character.
 * The return value is 0‑6, where 0 means “no digit” (vowel or ignored
 * character).  The mapping matches the classic Soundex table.
 * ---------------------------------------------------------------------- */
static int soundex_digit(char ch)
{
    switch (ch) {
        case 'B': case 'F': case 'P': case 'V': return 1;
        case 'C': case 'G': case 'J': case 'K':
        case 'Q': case 'S': case 'X': case 'Z': return 2;
        case 'D': case 'T':                     return 3;
        case 'L':                               return 4;
        case 'M': case 'N':                     return 5;
        case 'R':                               return 6;
        default:                                return 0;   /* A,E,I,O,U,H,W,Y or non‑letters */
    }
}

/* ----------------------------------------------------------------------
 * main
 *
 * Compute and print the Soundex code of argv[1] or “EMPTY” if no argument.
 * ---------------------------------------------------------------------- */
int main(int argc, char *argv[])
{
    /* No argument – print the required message */
    if (argc < 2 || argv[1][0] == '\0') {
        puts("EMPTY");
        return 0;
    }

    const char *src = argv[1];
    char result[5];          /* 1 letter + 3 digits + terminating NUL */
    size_t pos = 0;          /* position in result (excluding the first letter) */
    int  prev_digit = -1;    /* previous non‑zero digit, for duplicate suppression */

    /* First character – keep it (upper‑cased) */
    result[0] = (char)toupper((unsigned char)src[0]);

    /* Process the rest of the input */
    for (size_t i = 1; src[i] != '\0' && pos < 3; ++i) {
        char ch = (char)toupper((unsigned char)src[i]);
        if (ch < 'A' || ch > 'Z')
            continue;               /* ignore non‑alphabetic characters */

        int digit = soundex_digit(ch);
        if (digit == 0)
            continue;               /* vowels and ignored letters produce no digit */

        if (digit == prev_digit)
            continue;               /* suppress consecutive duplicate digits */

        result[1 + pos] = (char)('0' + digit);
        ++pos;
        prev_digit = digit;
    }

    /* Pad with '0' if fewer than three digits were produced */
    while (pos < 3) {
        result[1 + pos] = '0';
        ++pos;
    }

    result[4] = '\0';               /* NUL‑terminate */

    puts(result);
    return 0;
}
